head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
scwin.clickListProcsStatCd = "";
scwin.clickListSchdlDd = "";
scwin.clickListTpClss = "";
scwin.clickIsurCd = "";
scwin.clickComNm = "";
scwin.clickBillSubmitDd = "";
scwin.clickListComiteDelibCaseSeq = "";
scwin.clickSpotIsuTrdMktTpCd = "";
scwin.clickListSchdlDd = "";
scwin.contnId = "";
scwin.startTime = "";
scwin.endTime = "";
scwin.timeMsg = '';
scwin.listType = "";
scwin.params = "";
scwin.pCnt = 1;

/**
 * @method
 * @name HashMap
 * @description 세션정보를 얻기위한 함수사용
 * @returns {void}
 * @hidden N
 */
scwin.HashMap = function() {
    this.map = new Array();
};
scwin.HashMap.prototype = {
    set: function(key, value) {
        this.map[key] = value.getValue();
    },
    get: function(key) {
        return this.map[key];
    },
    clear: function() {
        this.map = new Array();
    }
};
scwin.h_Data = new HashMap();

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name getPar
 * @description get Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = txb_COM_NM.getValue();
    arrPar[2] = 'A1';
    arrPar[3] = '2';
    arrPar[4] = SEARCH_TYP_APF;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name getParDtl
 * @description get Par Dtl 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParDtl = function(arrPar) {
    arrPar[0] = scwin.clickIsurCd;
    arrPar[1] = scwin.clickBzProcsNo;
    arrPar[2] = scwin.clickComNm;
    arrPar[3] = scwin.clickBillSubmitDd;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    if (js_dep_cd !== 'ZSYS') {
        panel_verify.hide();
    } else {
        $c.cm.setColumnProp(grd_List, 'BZPROCSNO', 'Show', 'true');
        $c.cm.setColumnProp(grd_List, 'CONTNID', 'Show', 'true');
        $c.cm.setColumnProp(grd_List, 'LISTCOMITEDELIBCASESEQ', 'Show', 'true');
        $c.cm.setColumnProp(grd_List, 'COMITECASENO', 'Show', 'true');
    }
    edt_SDate.setValue("20180101");
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    chb_Grp_All.setValue(1);
    let strSRH_MENU = "상장예비심사신청현황(STF07100)^stf07100,";
    strSRH_MENU += "공모예정사항 및 재무사항(STF07170)^stf07170,";
    strSRH_MENU += "의무보유주식의 처분(STF07070)^stf07070,";
    strSRH_MENU += "신규상장심사(STF07180)^stf07180,";
    strSRH_MENU += "상장예비심사결과 상세조회(STF60002)^stf60002,";
    strSRH_MENU += "상장위원회 조회(STF60003)^stf60003,";
    strSRH_MENU += "심사관련 주요 이슈사항(STF60011)^stf60011";
    cmb_SRH_MENU.CBData = strSRH_MENU;
    cmb_SRH_MENU.setSelectedIndex(0);
    // setObjectValue(txb_SRH_FROM_TO_ITM,  "접수일");

    const strORD_ITM = " ^ ,회사명^comNm,파일명^attachFileNm,등록일^searchDate";
    cmb_ORD_ITM.CBData = strORD_ITM;
    cmb_ORD_ITM.setSelectedIndex(0);
    const strORD_METH = " ^ ,오름차순^asc,내림차순^desc";
    cmb_ORD_METH.CBData = strORD_METH;
    cmb_ORD_METH.setSelectedIndex(0);
    await scwin.listKeyword();
};

/**
 * @method
 * @name listKeyword
 * @description list Keyword 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listKeyword = async function() {
    const sbmOptions = {
        id : "sbm_dts_kwd",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_kwd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (!$c.stf.checkEmptyValue(edt_SDate, "검색기간 시작일")) return false;
    if (!$c.stf.checkEmptyValue(edt_SDate, "검색기간 종료일")) return false;
    if (!$c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        return false;
    }
    if ($c.ut.trim(txb_FileContent.getValue()).length === 1) {
        await $c.win.alert("검색어는 두자이상 입력이 필요합니다.");
        return false;
    }
    if ($c.ut.trim(txb_FileName.getValue()).length === 1) {
        await $c.win.alert("파일명는 두자이상 입력이 필요합니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_Grp_HWP, chb_Grp_DOC, chb_Grp_PDF];
    if (chb_Grp_All.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (await scwin.checkForm()) {
        scwin.listType = '1';
        await scwin.listSync();
    }
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    scwin.startTime = new Date().getTime();
    url += "&ElasticSearchURL=" + "/api/elastic/search";
    url += scwin.getListPrarams();
    url += "&screenId=" + cmb_SRH_MENU.BindColVal;
    url += "&attachBinfileContent=" + txb_FileContent.getValue();
    url += "&EMP_NO=" + js_emp_no;
    url += "&PN=companyCode^screenId^startSearchDate^endSearchDate^attachBinfileContent^attachFileNm^fileType^sortingCriteria^sortingMethod";
    if (chk_Exclusion.getValue() === 'Y') {
        const sbmOptions = {
            id : "sbm_dts_filter",
            action : "/ListedSearch.do",
            ref : "",
            target : "dts_filter=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        const sbmOptions = {
            id : "sbm_dts_List",
            action : "/ListedSearch.do",
            ref : "",
            target : "dts_List=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
    grd_List.Redraw = false;
};

/**
 * @method
 * @name listSyncRdb
 * @description list Sync Rdb 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSyncRdb = async function() {
    scwin.startTime = new Date().getTime();
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&SCREN_ID=" + "ULDSTF24703.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&outputMessageId=LIST_SEARCH_ATTACH_FILE_RDB";
    url += scwin.getListQueryId();
    url += scwin.getListPraramsRdb();
    if (chk_Exclusion.getValue() === 'Y') {
        const sbmOptions = {
            id : "sbm_dts_filter",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_filter=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        const sbmOptions = {
            id : "sbm_dts_List",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_List=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
    grd_List.Redraw = false;
};

/**
 * @method
 * @name getListQueryId
 * @description get List Query Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListQueryId = function() {
    let queryId = "&queryId=";
    if (cmb_SRH_MENU.getSelectedIndex() === 0) queryId += "lds.stf.lstsrch.listInvstgApfm.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() === 1) queryId += "lds.stf.lstsrch.pubfnc.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() === 2) queryId += "lds.stf.lstsrch.prtdepowithd.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() === 3) queryId += "lds.stf.lstsrch.newlist.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() === 4) queryId += "lds.stf.lstsrch.listInvstgApfm_detail.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() === 5) queryId += "lds.stf.lstsrch.comite_case.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() === 6) queryId += "lds.stf.lstsrch.comitedelib.attachfile.select.condition";
    return queryId;
};

/**
 * @method
 * @name getListPrarams
 * @description get List Prarams 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListPrarams = function() {
    let fileExt = '';
    if (chk_IN_RST_YN.getValue() === 'Y') {
        if (scwin.params.indexOf("&P1") === -1) {
            scwin.params = "&P1=^" + cmb_SRH_MENU.BindColVal + "^19000101^19000101^^^^^";
        }
        scwin.pCnt = scwin.pCnt + 1;
    } else {
        scwin.params = "";
        scwin.pCnt = 1;
    }
    scwin.params += "&P" + scwin.pCnt + "=" + txb_ISUR_CD.getValue();
    scwin.params += "^" + cmb_SRH_MENU.BindColVal;
    scwin.params += "^" + edt_SDate.getValue();
    scwin.params += "^" + edt_EDate.getValue();
    scwin.params += "^" + txb_FileContent.getValue();
    scwin.params += "^" + txb_FileName.getValue();
    if (chb_Grp_HWP.getValue() === 'Y') fileExt += 'hwp,hwpx,';
    if (chb_Grp_DOC.getValue() === 'Y') fileExt += 'doc,docx,';
    if (chb_Grp_PDF.getValue() === 'Y') fileExt += 'pdf,';
    if (chb_Grp_All.getValue() === 'Y') fileExt = '';
    fileExt = fileExt.replace(/,$/, '');
    scwin.params += "^" + fileExt;
    let vSortingCriteria = '';
    if (cmb_ORD_ITM.getSelectedIndex() > 0) vSortingCriteria = cmb_ORD_ITM.BindColVal;
    scwin.params += "^" + vSortingCriteria;
    let vSortingMethod = '';
    if (cmb_ORD_METH.getSelectedIndex() > 0) vSortingMethod = cmb_ORD_METH.BindColVal;
    scwin.params += "^" + vSortingMethod;
    return scwin.params;
};

/**
 * @method
 * @name getListPraramsRdb
 * @description get List Prarams Rdb 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListPraramsRdb = function() {
    const params = "";
    let fileExt = '';
    if (chb_Grp_HWP.getValue() === 'Y') fileExt += 'hwp,hwpx,';
    if (chb_Grp_DOC.getValue() === 'Y') fileExt += 'doc,docx,';
    if (chb_Grp_PDF.getValue() === 'Y') fileExt += 'pdf,';
    if (chb_Grp_All.getValue() === 'Y') fileExt = '';
    fileExt = fileExt.replace(/,$/, '');
    scwin.params += "&SCREN_ID=" + "ULDSTF24703.xml";
    scwin.params += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    scwin.params += "&inputMessageId=LIST_SEARCH_ATTACH_FILE_RDB";
    scwin.params += "&{P}EMP_NO=" + js_emp_no;
    scwin.params += "&{P}ISUR_CD=" + txb_ISUR_CD.getValue();
    scwin.params += "&{P}SPOT_ISU_TRD_MKT_TP_CD=2";
    scwin.params += "&{P}SRH_FROM=" + edt_SDate.getValue();
    scwin.params += "&{P}SRH_TO=" + edt_EDate.getValue();
    scwin.params += "&{P}FILE_NAME=" + txb_FileName.getValue();
    scwin.params += "&{P}FILE_EXT=" + fileExt;
    scwin.params += "&{P}FILE_SIZE_FROM=";
    scwin.params += "&{P}FILE_SIZE_TO=";
    scwin.params += "&{P}ORD_ITEM=";
    scwin.params += "&{P}ORDER_BY=";
    return scwin.params;
};

/**
 * @method
 * @name listFilter
 * @description list Filter 처리
 * @returns {void}
 * @hidden N
 */
scwin.listFilter = function() {
    scwin.h_Data.clear();
    for (let i = 1; i <= dts_filter.getRowCount(); i++) {
        scwin.h_Data.set(scwin.getMapkey(dts_filter, i), 'Y');
    }
    if (chk_Exclusion.getValue() === "Y") scwin.listExclusion();

    else {
        scwin.listInclusion();
    }
};

/**
 * @method
 * @name getMapkey
 * @description get Mapkey 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} idx idx
 * @returns {void}
 * @hidden N
 */
scwin.getMapkey = function(obj, idx) {
    let mapKey = "";
    mapKey = obj.getCellData(idx, "BZPROCSNO") + obj.getCellData(idx, "LISTCOMITEDELIBCASESEQ") + obj.getCellData(idx, "COMITECASENO") + obj.getCellData(idx, "CONTNID") + obj.getCellData(idx, "ATTACHFILENM");
    return mapKey;
};

/**
 * @method
 * @name listInclusion
 * @description list Inclusion 처리
 * @returns {void}
 * @hidden N
 */
scwin.listInclusion = function() {
    dts_List.setBroadcast(false);
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (scwin.h_Data.get(scwin.getMapkey(dts_List, i)) !== 'Y') {
            dts_List.removeRow(i);
            i--;
        }
    }
    dts_List.setBroadcast(true, true);
};

/**
 * @method
 * @name listExclusion
 * @description list Exclusion 처리
 * @returns {void}
 * @hidden N
 */
scwin.listExclusion = function() {
    dts_List.setBroadcast(false);
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (scwin.h_Data.get(scwin.getMapkey(dts_List, i)) === 'Y') {
            dts_List.removeRow(i);
            i--;
        }
    }
    dts_List.setBroadcast(true, true);
};

/**
 * @method
 * @name listCompleted
 * @description list Completed 처리
 * @returns {void}
 * @hidden N
 */
scwin.listCompleted = function() {
    grd_List.Redraw = true;
    scwin.footnote(panel_page, dts_List.getRowCount(), dts_List.getCellData(dts_List.getRowCount(), "TOTALCOUNT"));
    const endTime = new Date().getTime();
    let pt = scwin.endTime - scwin.startTime;
    edt_performance.setValue("" + (pt / 1000) % 60 + "s");
};

/**
 * @method
 * @name footnote
 * @description footnote 처리
 * @param {String} panelID panelID
 * @param {*} localCnt localCnt
 * @param {*} allCnt allCnt
 * @returns {void}
 * @hidden N
 */
scwin.footnote = function(panelID, localCnt, allCnt) {
    let vText = "<span style='font-size__9pt; font-family:굴림; color:#212863;'>총건수: </span><span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold'>" + $c.stf.FormatNumberEx(localCnt);
    if (allCnt > 200) {
        vText += " (총 " + $c.stf.FormatNumberEx(allCnt) + "개)";
    }
    vText += "</span>";
    panelID.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap>" + vText + "</td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.stf.doLogSave("ULDSTF24703.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "상장자료상세검색", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name getContnId
 * @description get Contn Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getContnId = function() {
    return scwin.contnId;
};

/**
 * @method
 * @name invstgApfm1
 * @description 0
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.invstgApfm1 = async function(row) {
    // 0

    // clickBzProcsNo
    // clickSpotIsuTrdMktTpCd
    // clickListTpClss

    let url = "/lstinvstg/ListPrelmInvstg.do?method=loadDetailView&nowPage=20";
    url += "&bzProcsNo=" + scwin.clickBzProcsNo;
    url += "&ldMktTpCd=" + scwin.clickSpotIsuTrdMktTpCd;
    url += "&listTpClssCd=" + scwin.clickListTpClss;
    await $c.frame.CreateDialogFrame("JLDSTF07110.jsp", url, "예비심사 청구계획 처리", 150, 0, 1000, 900, "window");

};

/**
 * @method
 * @name pubFnc
 * @description 1
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.pubFnc = async function(row) {
    // 1

    // clickListProcsStatCd
    let frameId = "frameID=" + frame.FrameID;
    await $c.frame.CreateDialogFrame("ULDSTF07171.gfm", "/lstinvstg/ULDSTF07171.gfm?" + frameId, "공모예정및재무사항 처리", 50, 50, 1000, 800, "window");
};

/**
 * @method
 * @name prtdepoWithd
 * @description 2
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prtdepoWithd = async function(row) {
    // 2

    // clickBzProcsNo
    let frameId = "&frameID=" + frame.FrameID;
    let url = "/lstinvstg/ULDSTF07071.gfm?BZ_PROCS_NO=" + scwin.clickBzProcsNo + frameId;
    await $c.frame.CreateDialogFrame("DLG_PDW", url, "의무보유주식의 처분 관리", 100, 100, 710, 450, "window");
};

/**
 * @method
 * @name invstgApfm2
 * @description 3
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.invstgApfm2 = async function(row) {
    // 3

    // clickListProcsStatCd
    // clickListSchdlDd
    // clickListTpClss
    let frameId = "?frameID=" + frame.FrameID;
    await $c.frame.CreateDialogFrame("ULDSTF07181.gfm", "/lstinvstg/ULDSTF07181.gfm" + frameId, "신규상장심사 처리", 100, 50, 1000, 800, "window");
};

/**
 * @method
 * @name comiteDelib
 * @description 4
 * @param {Number} row 행 인덱스
