 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_indexingElasitcSearch_onclick = async function() {
    switch (cmb_SRH_MENU.getSelectedIndex()) {
        case 0:
            list_invstg_attach(dts_List.getCellData(dts_List.getRowPosition(), "BZPROCSNO"), "00", "10"); // 예심
            break;
        case 1:
            list_invstg_attach(dts_List.getCellData(dts_List.getRowPosition(), "BZPROCSNO"), "00", "04"); // 공모
            break;
        case 2:
            prtdepo_withd_attach(dts_List.getCellData(dts_List.getRowPosition(), "PRTDEPO_ID"), dts_List.getCellData(dts_List.getRowPosition(), "PRTDEPO_WITHD_APPL_SEQ")); // 의무보유
            break;
        case 3:
            list_invstg_attach(dts_List.getCellData(dts_List.getRowPosition(), "BZPROCSNO"), "00", "40"); // 상장심사
            break;
        case 4:
            comite_rslt_attach(dts_List.getCellData(dts_List.getRowPosition(), "BZPROCSNO"), dts_List.getCellData(dts_List.getRowPosition(), "COMITEDD"), "2"); // 예심상세
            break;
        case 5:
            list_comite_case_file(dts_List.getCellData(dts_List.getRowPosition(), "LISTCOMITEDELIBCASESEQ")); // 상장위원회
            break;
        case 6:
            list_invstg_isue_file(dts_List.getCellData(dts_List.getRowPosition(), "CONTNID")); // 이슈사항
            break;
    }
    await $c.win.alert("인덱싱 처리 요청하였습니다.");
};

