            txb_SRH_FROM_TO_ITM.setValue("제출일");
            vSRH_SCRN = "stf07100"; // 예비심사
            break;
        case 1:
            txb_SRH_FROM_TO_ITM.setValue("제출일");
            vSRH_SCRN = "stf07170"; // 공모
            break;
        case 2:
            txb_SRH_FROM_TO_ITM.setValue("제출일");
            vSRH_SCRN = "stf07070"; // 의무보유
            break;
        case 3:
            txb_SRH_FROM_TO_ITM.setValue("제출일");
            vSRH_SCRN = "stf07180"; // 상장심사
            break;
        case 4:
            txb_SRH_FROM_TO_ITM.setValue("제출일");
            vSRH_SCRN = "stf60002"; // 예비심사 상세결과
            break;
        case 5:
            txb_SRH_FROM_TO_ITM.setValue("위원회일");
