/**
 * @method
 * @name grd_List_oncopy
 * @description grd_List oncopy 이벤트
 * @param {*} lStarRow lStarRow
 * @param {String} bstrStartColId bstrStartColId
 * @param {*} lEndRow lEndRow
 * @param {String} bstrEndColId bstrEndColId
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncopy = function(lStarRow, bstrStartColId, lEndRow, bstrEndColId) {
    let strMatrix = "";
    const statCol = grd_List.getColumnIndex(bstrStartColId);
    const endCol = grd_List.getColumnIndex(bstrEndColId);
    for (let i = lStarRow; i <= lEndRow; i++) {
        if (dts_List.RowMark(i) === 1) {
            strMatrix += scwin.getRowText(i, statCol, endCol, grd_List); // CopyToClipboard(StartRow,startColid,EndRow,EndColid,grdObj)

        }
    }
    if (strMatrix !== "") {
        window.clipboardData.setData("Text", strMatrix);
        txb_Msg.setValue("클립보드에 복사되었습니다.");
        scwin.timeMsg = setTimeout("fn_clearMsg()", 3000);
    }
};

